command:
set -eu
BASE=/workspace/omega_runtime/extensions/ingress_v4
LOG=/workspace/omega_runtime/state/logs/ingress_gateway_v4.log
umask 077
tmux new-session -d -s omega-fusion-v4-canary "cd $BASE && PYTHONPATH=. exec python3 -m omega.ingress_gateway serve --owner gabriel --machine omega-vps --port 8788 >>$LOG 2>&1"
python3 - <<'PY'
from pathlib import Path
import urllib.request,time
token=Path('/workspace/omega_runtime/private/ingress-gabriel.token').read_text().strip()
r=urllib.request.Request('http://127.0.0.1:8788/v1/health',headers={'Authorization':'Bearer '+token})
for _ in range(15):
 try:
  with urllib.request.urlopen(r,timeout=2) as x:print('CANARY',x.status);break
 except Exception:time.sleep(.3)
else:raise AssertionError('candidate not alive')
PY
tmux kill-session -t omega-fusion-v4-canary
tmux has-session -t omega-ingress
tmux kill-session -t omega-ingress
tmux new-session -d -s omega-ingress "cd $BASE && PYTHONPATH=. exec python3 -m omega.ingress_gateway serve --owner gabriel --machine omega-vps --port 8787 >>$LOG 2>&1"
python3 - <<'PY'
from pathlib import Path
import urllib.request,urllib.error,time
t=Path('/workspace/omega_runtime/private/ingress-gabriel.token').read_text().strip()
ok=urllib.request.Request('http://127.0.0.1:8787/v1/health',headers={'Authorization':'Bearer '+t})
for _ in range(15):
 try:
  with urllib.request.urlopen(ok,timeout=2) as r:print('V4_ACTIVE_HEALTH',r.status);break
 except Exception:time.sleep(.3)
else:raise AssertionError('V4 not alive')
try:urllib.request.urlopen('http://127.0.0.1:8787/v1/health',timeout=2)
except urllib.error.HTTPError as e:
 print('UNAUTHENTICATED_HEALTH',e.code)
 assert e.code==401
else:raise AssertionError('not protected')
PY
